#include "full_dive/visual_chip/VisualSceneSemanticExtractor.h"
#include <algorithm>
namespace dnxr { float VisualSceneSemanticExtractor::clamp01(float v){return std::max(0.0f,std::min(1.0f,v));} VisualSceneSemantics VisualSceneSemanticExtractor::extract(const VirtualSceneFrame& s) const { VisualSceneSemantics o; o.nearObstacles01=clamp01(std::max(s.nearObstacle01,s.nearObstacleDensity01)); o.walkingCorridor01=clamp01(std::max(s.navigationCorridor01,s.walkableCorridorConfidence01)); o.handsVisible01=clamp01(s.handVisibility01); o.avatarBodyVisible01=clamp01(std::max(s.avatarBody01,s.bodyVisibility01)); o.interactiveObjects01=clamp01(std::max(s.salientObject01,s.interactiveObjectPriority01)); o.gazeDirectionConfidence01=clamp01(1.0f-s.motionFlow01); o.horizon01=clamp01(s.horizonStability01); o.globalMotion01=clamp01(s.motionFlow01); o.visualDanger01=clamp01(std::max(s.hazard01,s.nearObstacle01)); o.importantText01=clamp01(s.textSymbol01); return o;} }
